<script setup lang="ts">
import { computed, ref } from 'vue'
import { Monitor, ShieldCheck, RefreshCw, Sun, Moon } from '@lucide/vue'
import type { Catalog, Hardware, ManagedState, SetupState, Preparation } from '@veltria/contracts'
import SetupWizard from './SetupWizard.vue'
import PreparationProgress from './PreparationProgress.vue'
import StorageNotice from './StorageNotice.vue'
import { t, bytes, locale } from './i18n'
const props = defineProps<{ catalog: Catalog | null; hardware: Hardware | null; state: SetupState | null; managed: ManagedState | null; preparation?: Preparation; connected: boolean; busy: boolean; loading: boolean; error: string; dark: boolean }>()
const emit = defineEmits<{ select: [id: string]; scan: [directory?: string]; prepare: [revision: string]; refresh: []; reconnect: []; theme: []; language: []; pause: [] }>()
const reviewing = ref(false), others = ref(false)
const choices = computed(() => (props.catalog?.models || []).filter(item => !item.profile.adaptation).sort((a,b) => ['recommended','limited','unknown','unsupported'].indexOf(a.recommendation.level) - ['recommended','limited','unknown','unsupported'].indexOf(b.recommendation.level)))
const primary = computed(() => choices.value.find(item => item.profile.id === props.catalog?.selectedModelId) || choices.value[0])
const alternative = computed(() => choices.value.find(item => item.profile.id !== primary.value?.profile.id))
const profileWorking = computed(() => ['downloading','verifying','starting'].includes(props.preparation?.status || ''))
const working = computed(() => ['downloading','installing','preparing'].includes(props.managed?.status || '') || profileWorking.value)
function choose(id: string) { reviewing.value = false; const entry = props.catalog?.configurations.find(item => item.configuration.modelId === id); if (entry) emit('select', entry.id) }
</script>
<template>
  <div class="welcome-shell">
    <header class="welcome-header"><a class="welcome-brand" href="#"><img class="brand-logo" :src="dark ? '/kobocraft-dark.svg' : '/kobocraft-light.svg'" alt="" width="30" height="30"/><span>KOBOCRAFT</span></a><div><button class="text-button" @click="emit('language')">{{ locale === 'es' ? 'English' : 'Español' }}</button><button class="icon-button" :aria-label="t(dark ? 'Cambiar a modo claro' : 'Cambiar a modo oscuro')" @click="emit('theme')"><Sun v-if="dark" :size="20"/><Moon v-else :size="20"/></button></div></header>
    <main id="content" class="welcome-content">
      <div class="welcome-intro"><h1 tabindex="-1">{{ t('Tu PC, lista para imaginar.') }}</h1><p>{{ t('Prepara un modelo para empezar a crear imágenes localmente. Kobocraft se encarga de instalarlo.') }}</p></div>
      <p class="welcome-reason" role="status">{{ t(connected ? 'Servicio local conectado' : 'Servicio local desconectado') }}</p>
      <p v-if="loading" role="status">{{ t('Detectando el hardware del servicio…') }}</p>
      <div v-if="hardware" class="welcome-hardware"><Monitor :size="19"/><span>{{ hardware.gpus.map(gpu => gpu.name).join(', ') || hardware.cpu.name }}</span><span>{{ bytes(hardware.gpus[0]?.vramTotal ?? null) }} VRAM</span><span>{{ bytes(hardware.ram.total) }} RAM</span></div>
      <div v-if="error" class="warning" role="alert"><p>{{ t(error) }}</p><button class="secondary-button" :disabled="loading" @click="emit('reconnect')"><RefreshCw :size="16"/>{{ t('Volver a conectar') }}</button></div>
      <template v-if="primary">
        <section class="welcome-recommendation" :aria-labelledby="'welcome-model'"><div><p class="welcome-fit">{{ t(primary.recommendation.level === 'recommended' ? 'Recomendado para tu equipo' : primary.recommendation.level === 'limited' ? 'Con limitaciones' : 'Compatibilidad sin confirmar') }}</p><h2 id="welcome-model">{{ primary.profile.model }}</h2><p>{{ t(primary.profile.description) }}</p><p class="welcome-reason">{{ t(primary.recommendation.reason) }}</p><button v-if="!reviewing" class="primary-button" :disabled="!connected || busy || loading" @click="reviewing = true">{{ t('Instalar y preparar mi PC') }}</button></div><aside><ShieldCheck :size="25"/><strong>{{ t('Local') }}</strong><p>{{ t('Sin cuentas. Imágenes en tu equipo.') }}</p></aside></section>
        <template v-if="!reviewing && !working">
          <section v-if="alternative" class="welcome-alternative"><h3>{{ alternative.profile.model }}</h3><p>{{ t(alternative.profile.description) }}</p><p class="welcome-reason">{{ t(alternative.recommendation.reason) }}</p><button class="text-button" :disabled="busy || !connected" @click="choose(alternative.profile.id)">{{ t('Elegir este modelo') }}</button></section>
          <button class="text-button" :aria-expanded="others" @click="others = !others">{{ t(others ? 'Ver menos opciones' : 'Ver todos los modelos') }}</button>
          <section v-if="others" class="welcome-others"><article v-for="item in choices" :key="item.profile.id"><h3>{{ item.profile.model }}</h3><p>{{ t(item.recommendation.reason) }}</p><button class="secondary-button" :disabled="busy || !connected" @click="choose(item.profile.id)">{{ t('Elegir este modelo') }}</button></article></section>
        </template>
        <button v-if="reviewing && !working" class="text-button" @click="reviewing = false">{{ t('Volver a elegir modelo') }}</button>
        <section v-if="profileWorking && managed?.status !== 'preparing'" class="preparation-feedback"><p role="status">{{ t(preparation!.message) }}</p><PreparationProgress :label="preparation!.status === 'downloading' ? 'Descarga del modelo' : preparation!.status === 'verifying' ? 'Comprobando los archivos' : 'Comprobando el modelo y el motor'" :received="preparation!.status === 'downloading' ? preparation!.received : undefined" :total="preparation!.status === 'downloading' ? preparation!.total : undefined" :connected="connected"/><button class="secondary-button" :disabled="busy || !connected" @click="emit('pause')">{{ t('Pausar') }}</button></section>
        <StorageNotice v-if="preparation?.status === 'error' && preparation.storageIssue && managed?.status !== 'error'" :issue="preparation.storageIssue" :disabled="busy || !connected" @recheck="reviewing = true; emit('refresh')" @relocate="reviewing = true"/>
        <p v-else-if="preparation?.status === 'error' && !preparation.storageIssue" class="warning" role="alert">{{ t(preparation.message) }}</p>
        <SetupWizard v-if="!profileWorking && (reviewing || working || (managed && managed.status !== 'idle')) || managed?.status === 'preparing'" inline :state="state" :managed="managed" :preparation="preparation" :catalog="catalog" :connected="connected" :busy="busy" :error="''" @scan="directory => emit('scan', directory)" @refresh="emit('refresh')" @prepare="revision => emit('prepare', revision)" @close="emit('refresh')"/>
      </template>
      <footer class="welcome-footer"><p>{{ t('Al terminar la preparación y comprobar el modelo, se abrirá tu espacio de creación.') }}</p><p>{{ t('Video experimental: primero prepara las imágenes. Después podrás revisar sus requisitos y descarga en Crear → Video.') }}</p></footer>
    </main>
  </div>
</template>
<style scoped>
.welcome-shell{min-height:100dvh;background:var(--bg);color:var(--text)}.welcome-header{max-width:1120px;margin:auto;padding:26px 36px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.welcome-brand{display:inline-flex;align-items:center;gap:10px;font-weight:650;font-size:19px;letter-spacing:.08em;text-decoration:none;color:var(--text)}.welcome-brand img{width:30px;height:30px;border-radius:6px;display:block;flex-shrink:0}.welcome-header>div{display:flex;align-items:center;gap:22px}.welcome-content{max-width:980px;margin:auto;padding:64px 36px 36px}.welcome-intro{max-width:630px}.welcome-intro h1{font-size:clamp(30px,4vw,46px);font-weight:500;letter-spacing:-.025em;line-height:1.15;margin:0 0 18px}.welcome-content p{font-size:15px;line-height:1.7;color:var(--muted);margin:12px 0}.welcome-hardware{display:flex;gap:12px;flex-wrap:wrap;align-items:center;padding:20px 0;margin-top:28px;border-block:1px solid var(--line);font-size:13px;color:var(--muted)}.welcome-recommendation{display:grid;grid-template-columns:1fr 170px;gap:48px;padding:34px 0;border-bottom:1px solid var(--line)}.welcome-recommendation h2{font-size:28px;font-weight:500;line-height:1.25;letter-spacing:-.02em}.welcome-recommendation .welcome-fit{color:var(--accent-text);font-size:13px;margin-top:0}.welcome-content .welcome-reason{font-size:13px;max-width:65ch}.welcome-recommendation .primary-button{margin-top:14px}.welcome-recommendation aside{border-left:1px solid var(--line);padding-left:28px;align-self:center}.welcome-recommendation aside svg{color:var(--accent-text)}.welcome-recommendation aside strong{display:block;font-size:24px;font-weight:500;margin-top:14px}.welcome-recommendation aside p{font-size:13px}.welcome-alternative{padding:26px 0 8px}.welcome-alternative h3,.welcome-others h3{font-size:17px;font-weight:500}.welcome-alternative>p{font-size:14px;max-width:65ch}.welcome-others article{padding:22px 0;border-bottom:1px solid var(--line)}.welcome-footer{border-top:1px solid var(--line);margin-top:30px;padding-top:12px}.welcome-footer p{font-size:12px;max-width:75ch}.welcome-content>button{margin-top:12px}@media(max-width:600px){.welcome-header{padding:20px}.welcome-content{padding:36px 20px}.welcome-recommendation{grid-template-columns:1fr;gap:24px}.welcome-recommendation aside{border-left:0;padding-left:0;display:flex;gap:12px;align-items:center}.welcome-recommendation aside strong{margin:0;font-size:18px}.welcome-recommendation aside p{margin:0}.welcome-recommendation .primary-button{width:100%;white-space:normal}.welcome-hardware span:first-of-type{width:calc(100% - 32px)}}
</style>
